import type { Persona } from '@wener/ai/agent/persona';
import type { ToolSet } from 'ai';
import {
	type AgentCommandExecutor,
	type AgentCommandRuntime,
	type AgentTerminalResult,
	type CreateAgentCodingToolsOptions,
	createAgentCodingTools,
} from '../agent-coding';
import {
	type AgentWorkspace,
	type AgentWorkspaceContext,
	composeAgentInstructions,
	createAgentWorkspaceReadTools,
} from '../agent-work';

export type AgentPlaygroundMode = 'chat' | 'coding' | 'work';

export const AgentRuntimeIdentityChangedCancelReason = 'agent-runtime-identity-changed';

export type AgentPlaygroundRuntimeOptions = {
	coding?: Omit<CreateAgentCodingToolsOptions, 'runtime' | 'workspace'>;
	commandRuntime?: AgentCommandRuntime;
	context?: AgentWorkspaceContext;
	mode: AgentPlaygroundMode;
	persona?: Persona;
	workspace: AgentWorkspace;
};

export type AgentPlaygroundRuntimeConfiguration = {
	instructions: string;
	tools?: ToolSet;
};

export function createAgentPlaygroundRuntimeConfiguration({
	coding,
	commandRuntime,
	context,
	mode,
	persona,
	workspace,
}: AgentPlaygroundRuntimeOptions): AgentPlaygroundRuntimeConfiguration {
	const instructions = composeAgentInstructions({
		context: mode === 'chat' ? undefined : context,
		persona,
	}).instructions;
	if (mode === 'chat') return { instructions };
	const readonlyTools = createAgentWorkspaceReadTools(workspace);
	if (mode === 'work') return { instructions, tools: readonlyTools };
	if (!commandRuntime) return { instructions, tools: readonlyTools };
	return {
		instructions,
		tools: {
			...readonlyTools,
			...createAgentCodingTools({ ...coding, runtime: commandRuntime, workspace }),
		},
	};
}

export function isUnsafeAgentTerminalResult(result: AgentTerminalResult): boolean {
	return result.poisoned === true || result.settled === false || result.mutationMayContinue === true;
}

export function createUnavailableAgentExecutor(message: string): AgentCommandExecutor {
	return {
		async execute() {
			return {
				durationMs: 0,
				exitCode: 127,
				settled: true,
				stderr: `${message}\n`,
				stdout: '',
				truncated: false,
			};
		},
	};
}

'use client';

import { type MutableRefObject, useCallback, useLayoutEffect, useRef, useState } from 'react';
import type { AgentCommandRuntime } from '../agent-coding';
import { AgentRuntimeIdentityChangedCancelReason } from './playground-runtime';

export function useCommandRuntimeTransition(
	candidate: AgentCommandRuntime,
	identity: unknown,
	poisonedRef: MutableRefObject<boolean>,
) {
	const [commandRuntime, setCommandRuntime] = useState(candidate);
	const [poisoned, setPoisonedState] = useState(false);
	const [revision, setRevision] = useState(0);
	const activeRuntime = useRef(commandRuntime);
	const generation = useRef(0);
	const setPoisoned = useCallback(
		(value: boolean) => {
			poisonedRef.current = value;
			setPoisonedState(value);
		},
		[poisonedRef],
	);

	useLayoutEffect(() => {
		let current = true;
		const previousRuntime = activeRuntime.current;
		const runtimeReplaced = previousRuntime !== candidate;
		const transitionGeneration = ++generation.current;
		const previousState = previousRuntime.getState();
		if (previousState.running || previousState.mutationMayContinue || previousState.poisoned) setPoisoned(true);
		void previousRuntime.cancelCurrentAndWait(AgentRuntimeIdentityChangedCancelReason).then((settledState) => {
			if (!current || transitionGeneration !== generation.current) return;
			if (!runtimeReplaced) {
				setPoisoned(settledState.poisoned);
				return;
			}
			if (settledState.mutationMayContinue) {
				setPoisoned(true);
				return;
			}
			activeRuntime.current = candidate;
			setCommandRuntime(candidate);
			setPoisoned(candidate.getState().poisoned);
		});
		setRevision((value) => value + 1);
		return () => {
			current = false;
			poisonedRef.current = true;
			activeRuntime.current.cancelCurrent(AgentRuntimeIdentityChangedCancelReason);
		};
	}, [candidate, identity, poisonedRef, setPoisoned]);

	return { commandRuntime, generation, poisoned, revision, setPoisoned };
}

'use client';

import {
	createJustBashAgentSession,
	createJustBashWorkspaceFromLoader,
	type JustBashModuleLoader,
} from '@wener/common/fs/just-bash';
import { useEffect, useState } from 'react';
import { type AgentCommandExecutor, createJustBashCommandExecutor } from '../agent-coding';
import type { AgentWorkspace } from '../agent-work';

export type JustBashExecutorState = {
	error?: Error;
	executor?: AgentCommandExecutor;
	status: 'disabled' | 'error' | 'idle' | 'loading' | 'ready';
};

export function useJustBashExecutor(options: {
	enabled: boolean;
	loader?: JustBashModuleLoader;
	onWorkspaceChanged: () => void;
	workspace: AgentWorkspace;
}): JustBashExecutorState {
	const { enabled, loader, onWorkspaceChanged, workspace } = options;
	const [state, setState] = useState<JustBashExecutorState>({ status: loader ? 'idle' : 'disabled' });
	useEffect(() => {
		let current = true;
		if (!loader) {
			setState({ status: 'disabled' });
			return () => {
				current = false;
			};
		}
		if (!enabled) {
			setState({ status: 'idle' });
			return () => {
				current = false;
			};
		}
		setState({ status: 'loading' });
		void createJustBashWorkspaceFromLoader(loader, {
			cwd: '/workspace',
			fs: workspace.fileSystem,
			fsRoot: workspace.rootPath,
			onWorkspaceChanged,
			workspaceRoot: '/workspace',
		}).then(
			(bashWorkspace) => {
				if (!current) return;
				const session = createJustBashAgentSession({ workspace: bashWorkspace });
				setState({ executor: createJustBashCommandExecutor(session), status: 'ready' });
			},
			(error: unknown) => {
				if (current) setState({ error: error instanceof Error ? error : new Error(String(error)), status: 'error' });
			},
		);
		return () => {
			current = false;
		};
	}, [enabled, loader, onWorkspaceChanged, workspace.fileSystem, workspace.id, workspace.rootPath]);
	return state;
}

